svg.script:
    const frame = document.getElementById("linux_frame");
    const V86_BUILD = "https:/" + "/copy.sh/v86/build/";
    const V86_BIOS = "https:/" + "/cdn.jsdelivr.net/gh/copy/v86@master/bios/";
    const V86_IMG = "https:/" + "/i.copy.sh/";

    const pageHtml = `<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8" />
  <style>
    body { margin: 0; background: #111; color: #eee; font-family: monospace; display: flex; flex-direction: column; height: 100vh; }
    #bar { padding: 8px 12px; background: #222; border-bottom: 1px solid #333; display: flex; gap: 10px; align-items: center; flex-wrap: wrap; }
    button { background: #2d6cdf; color: #fff; border: none; padding: 6px 12px; border-radius: 4px; cursor: pointer; font-family: monospace; font-weight: bold; }
    button:hover { background: #1b56c2; }
    #status { color: #0f0; margin-left: auto; font-size: 13px; }
    #screen_container { flex: 1; overflow: auto; padding: 8px; }
    #screen_container div { white-space: pre; font: 14px monospace; line-height: 14px; }
    canvas { display: block; margin: 0 auto; }
  </style>
  <script src="${V86_BUILD}libv86.js"><\/script>
</head>
<body>
  <div id="bar">
    <span><b>v86 x86 Emulator:</b></span>
    <button onclick="bootOS('buildroot')">1. Boot Buildroot Linux (Fast CLI)</button>
    <button onclick="bootOS('tinycore')">2. Boot TinyCore 11 (Desktop GUI)</button>
    <button onclick="bootOS('linux4')">3. Boot Linux 4 ISO</button>
    <span id="status">Select an OS above to boot...</span>
  </div>
  <div id="screen_container">
    <div></div>
    <canvas style="display:none"></canvas>
  </div>
  <script>
    let emulator = null;
    function bootOS(type) {
      if (emulator) { try { emulator.stop(); } catch (e) {} }
      const status = document.getElementById("status");
      status.textContent = "Downloading " + type + " image & BIOS...";

      const cfg = {
        wasm_path: "${V86_BUILD}v86.wasm",
        memory_size: 128 * 1024 * 1024,
        vga_memory_size: 8 * 1024 * 1024,
        screen_container: document.getElementById("screen_container"),
        bios: { url: "${V86_BIOS}seabios.bin" },
        vga_bios: { url: "${V86_BIOS}vgabios.bin" },
        autostart: true
      };

      if (type === "buildroot") {
        cfg.bzimage = { url: "${V86_IMG}buildroot-bzimage68.bin" };
        cfg.cmdline = "tsc=reliable mitigations=off random.trust_cpu=on";
      } else if (type === "tinycore") {
        cfg.cdrom = { url: "${V86_IMG}TinyCore-11.0.iso" };
      } else if (type === "linux4") {
        cfg.cdrom = { url: "${V86_IMG}linux4.iso" };
      }

      emulator = new V86(cfg);
      emulator.add_listener("emulator-ready", () => {
        status.textContent = "Running " + type + " (Click screen to capture mouse, Esc to release)";
      });
    }
  <\/script>
</body>
</html>`;

    const doc = frame.contentDocument || frame.contentWindow.document;
    doc.open();
    doc.write(pageHtml);
    doc.close();
